package homework.hw03;

import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * The SAME 30 public tests are used by students and the instructor.
 * Each passing test is worth 2 implementation points, for 60 points total.
 * Run the entire class. Do not edit this file.
 * Each test builds its own objects and is independent of execution order.
 */
public class Hw3PublicTest {
    // A controllable Strategy lets us check delegation without console output.
    private static class CountingWeapon implements WeaponBehavior {
        private final int value;
        private final String label;
        int damageCalls;
        int descriptionCalls;

        CountingWeapon(int value, String label) {
            this.value = value;
            this.label = label;
        }

        @Override
        public int damage() {
            damageCalls++;
            return value;
        }

        @Override
        public String description() {
            descriptionCalls++;
            return label;
        }
    }

    // A second observer type checks that the subject uses the interface.
    private static class RecordingObserver implements CombatObserver {
        int count;
        AttackEvent last;

        @Override
        public void update(AttackEvent event) {
            count++;
            last = event;
        }
    }

    // STRATEGY: 10 tests, 20 points.
    @Test
    void strategy01_attackDelegatesDamageExactlyOnce() {
        CountingWeapon weapon = new CountingWeapon(17, "Staff");
        GameCharacter hero = new GameCharacter("Queen", weapon);
        AttackEvent event = hero.attack();
        assertEquals(17, event.getDamage());
        assertEquals(1, weapon.damageCalls);
    }

    @Test
    void strategy02_attackDelegatesDescriptionExactlyOnce() {
        CountingWeapon weapon = new CountingWeapon(12, "Spear");
        AttackEvent event = new GameCharacter("King", weapon).attack();
        assertEquals("Spear", event.getWeaponDescription());
        assertEquals(1, weapon.descriptionCalls);
    }

    @Test
    void strategy03_switchChangesTheNextAttack() {
        GameCharacter hero = new GameCharacter("Queen", new SwordBehavior());
        assertEquals(10, hero.attack().getDamage());
        hero.setWeaponBehavior(new BowBehavior());
        AttackEvent event = hero.attack();
        assertEquals(6, event.getDamage());
        assertEquals("Bow", event.getWeaponDescription());
    }

    @Test
    void strategy04_setterKeepsTheCharacterAndStoresTheNewReference() {
        GameCharacter hero = new GameCharacter("Queen", new SwordBehavior());
        GameCharacter sameHero = hero;
        WeaponBehavior bow = new BowBehavior();
        hero.setWeaponBehavior(bow);
        assertSame(sameHero, hero);
        assertEquals("Queen", hero.getName());
        assertSame(bow, hero.getWeaponBehavior());
    }

    @Test
    void strategy05_setterDoesNotExecuteEitherWeaponMethod() {
        CountingWeapon oldWeapon = new CountingWeapon(10, "Old");
        CountingWeapon newWeapon = new CountingWeapon(8, "New");
        GameCharacter hero = new GameCharacter("King", oldWeapon);
        hero.setWeaponBehavior(newWeapon);
        assertEquals(0, oldWeapon.damageCalls);
        assertEquals(0, oldWeapon.descriptionCalls);
        assertEquals(0, newWeapon.damageCalls);
        assertEquals(0, newWeapon.descriptionCalls);
    }

    @Test
    void strategy06_oldWeaponStopsReceivingCallsAfterReplacement() {
        CountingWeapon first = new CountingWeapon(10, "First");
        CountingWeapon second = new CountingWeapon(8, "Second");
        GameCharacter hero = new GameCharacter("King", first);
        hero.attack();
        hero.setWeaponBehavior(second);
        hero.attack();
        assertEquals(1, first.damageCalls);
        assertEquals(1, first.descriptionCalls);
        assertEquals(1, second.damageCalls);
        assertEquals(1, second.descriptionCalls);
    }

    @Test
    void strategy07_twoCharactersCanShareTheSameWeapon() {
        CountingWeapon weapon = new CountingWeapon(9, "Shared staff");
        GameCharacter king = new GameCharacter("King", weapon);
        GameCharacter queen = new GameCharacter("Queen", weapon);
        assertEquals(9, king.attack().getDamage());
        assertEquals(9, queen.attack().getDamage());
        assertSame(weapon, king.getWeaponBehavior());
        assertSame(weapon, queen.getWeaponBehavior());
        assertEquals(2, weapon.damageCalls);
    }

    @Test
    void strategy08_eachAttackRecomputesDamageInsteadOfCachingIt() {
        WeaponBehavior changingWeapon = new WeaponBehavior() {
            private int nextDamage = 7;
            @Override public int damage() { return nextDamage++; }
            @Override public String description() { return "Growing staff"; }
        };
        GameCharacter hero = new GameCharacter("Queen", changingWeapon);
        assertEquals(7, hero.attack().getDamage());
        assertEquals(8, hero.attack().getDamage());
    }

    @Test
    void strategy09_aNewStrategyWorksThroughTheInterface() {
        WeaponBehavior iceWand = new WeaponBehavior() {
            @Override public int damage() { return 37; }
            @Override public String description() { return "Ice wand"; }
        };
        GameCharacter hero = new GameCharacter("Mage", new SwordBehavior());
        hero.setWeaponBehavior(iceWand);
        AttackEvent event = hero.attack();
        assertEquals(37, event.getDamage());
        assertEquals("Ice wand", event.getWeaponDescription());
    }

    @Test
    void strategy10_eachAttackReturnsAFreshEventWithTheCharacterName() {
        GameCharacter hero = new GameCharacter("Knight", new SwordBehavior());
        AttackEvent first = hero.attack();
        AttackEvent second = hero.attack();
        assertEquals("Knight", first.getCharacterName());
        assertEquals("Knight", second.getCharacterName());
        assertNotSame(first, second);
    }

    // OBSERVER: 10 tests, 20 points.
    @Test
    void observer01_registeredObserverReceivesTheReturnedEvent() {
        GameCharacter hero = new GameCharacter("Queen", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        AttackEvent event = hero.attack();
        assertEquals(1, log.getUpdateCount());
        assertSame(event, log.getLastEvent());
    }

    @Test
    void observer02_twoObserversReceiveTheSameEventObject() {
        CountingWeapon weapon = new CountingWeapon(6, "Bow");
        GameCharacter hero = new GameCharacter("King", weapon);
        CombatLog first = new CombatLog();
        RecordingObserver second = new RecordingObserver();
        hero.registerObserver(first);
        hero.registerObserver(second);
        AttackEvent event = hero.attack();
        assertEquals(1, first.getUpdateCount());
        assertEquals(1, second.count);
        assertSame(event, first.getLastEvent());
        assertSame(event, second.last);
        assertEquals(1, weapon.damageCalls);
        assertEquals(1, weapon.descriptionCalls);
    }

    @Test
    void observer03_duplicateRegistrationDoesNotDuplicateNotifications() {
        GameCharacter hero = new GameCharacter("King", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        hero.registerObserver(log);
        hero.attack();
        assertEquals(1, log.getUpdateCount());
    }

    @Test
    void observer04_removedObserverReceivesNoLaterAttack() {
        GameCharacter hero = new GameCharacter("Queen", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        AttackEvent first = hero.attack();
        hero.removeObserver(log);
        hero.attack();
        assertEquals(1, log.getUpdateCount());
        assertSame(first, log.getLastEvent());
    }

    @Test
    void observer05_removingAMissingObserverPreservesOtherSubscribers() {
        GameCharacter hero = new GameCharacter("King", new SwordBehavior());
        CombatLog registered = new CombatLog();
        hero.registerObserver(registered);
        hero.removeObserver(new CombatLog());
        hero.attack();
        assertEquals(1, registered.getUpdateCount());
    }

    @Test
    void observer06_registrationDoesNotReplayAnEarlierAttack() {
        GameCharacter hero = new GameCharacter("Queen", new BowBehavior());
        hero.attack();
        CombatLog late = new CombatLog();
        hero.registerObserver(late);
        assertEquals(0, late.getUpdateCount());
        assertNull(late.getLastEvent());
        AttackEvent next = hero.attack();
        assertEquals(1, late.getUpdateCount());
        assertSame(next, late.getLastEvent());
    }

    @Test
    void observer07_everyAttackProducesOneNotificationPerSubscriber() {
        GameCharacter hero = new GameCharacter("King", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        hero.attack();
        AttackEvent second = hero.attack();
        assertEquals(2, log.getUpdateCount());
        assertSame(second, log.getLastEvent());
    }

    @Test
    void observer08_repeatedRemovalIsHarmless() {
        GameCharacter hero = new GameCharacter("Queen", new BowBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        hero.removeObserver(log);
        hero.removeObserver(log);
        hero.attack();
        assertEquals(0, log.getUpdateCount());
    }

    @Test
    void observer09_reregisteredObserverReceivesFutureAttacks() {
        GameCharacter hero = new GameCharacter("Queen", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        hero.attack();
        hero.removeObserver(log);
        hero.attack();
        hero.registerObserver(log);
        AttackEvent finalAttack = hero.attack();
        assertEquals(2, log.getUpdateCount());
        assertSame(finalAttack, log.getLastEvent());
    }

    @Test
    void observer10_changingStrategyDoesNotPublishAnAttack() {
        GameCharacter hero = new GameCharacter("King", new SwordBehavior());
        CombatLog log = new CombatLog();
        hero.registerObserver(log);
        hero.setWeaponBehavior(new BowBehavior());
        assertEquals(0, log.getUpdateCount());
        AttackEvent event = hero.attack();
        assertEquals(1, log.getUpdateCount());
        assertEquals(6, log.getLastEvent().getDamage());
        assertSame(event, log.getLastEvent());
    }

    // DECORATOR: 10 tests, 20 points.
    @Test
    void decorator01_fireAddsFourDamage() {
        assertEquals(14, new FireWeapon(new SwordBehavior()).damage());
        assertEquals(10, new FireWeapon(new BowBehavior()).damage());
    }

    @Test
    void decorator02_fireAppendsItsDescription() {
        assertEquals("Sword + fire", new FireWeapon(new SwordBehavior()).description());
        assertEquals("Bow + fire", new FireWeapon(new BowBehavior()).description());
    }

    @Test
    void decorator03_powerDoublesDamage() {
        assertEquals(20, new PowerWeapon(new SwordBehavior()).damage());
        assertEquals(12, new PowerWeapon(new BowBehavior()).damage());
    }

    @Test
    void decorator04_powerAppendsItsDescription() {
        assertEquals("Sword x2", new PowerWeapon(new SwordBehavior()).description());
        assertEquals("Bow x2", new PowerWeapon(new BowBehavior()).description());
    }

    @Test
    void decorator05_powerOutsideFireGivesTwentyEight() {
        WeaponBehavior weapon = new PowerWeapon(new FireWeapon(new SwordBehavior()));
        assertEquals(28, weapon.damage());
        assertEquals("Sword + fire x2", weapon.description());
    }

    @Test
    void decorator06_fireOutsidePowerGivesTwentyFour() {
        WeaponBehavior weapon = new FireWeapon(new PowerWeapon(new SwordBehavior()));
        assertEquals(24, weapon.damage());
        assertEquals("Sword x2 + fire", weapon.description());
    }

    @Test
    void decorator07_theSameDecoratorCanBeAppliedMoreThanOnce() {
        WeaponBehavior fireTwice = new FireWeapon(new FireWeapon(new SwordBehavior()));
        WeaponBehavior powerTwice = new PowerWeapon(new PowerWeapon(new SwordBehavior()));
        assertEquals(18, fireTwice.damage());
        assertEquals("Sword + fire + fire", fireTwice.description());
        assertEquals(40, powerTwice.damage());
        assertEquals("Sword x2 x2", powerTwice.description());
    }

    @Test
    void decorator08_repeatedQueriesDoNotAccumulateOrChangeTheBase() {
        WeaponBehavior base = new SwordBehavior();
        WeaponBehavior decorated = new FireWeapon(base);
        assertEquals(14, decorated.damage());
        assertEquals(14, decorated.damage());
        assertEquals(10, base.damage());
        assertEquals("Sword", base.description());
    }

    @Test
    void decorator09_fireDelegatesEachMethodOnceForAnUnknownComponent() {
        CountingWeapon base = new CountingWeapon(13, "Axe");
        WeaponBehavior decorated = new FireWeapon(base);
        assertEquals(17, decorated.damage());
        assertEquals(1, base.damageCalls);
        assertEquals("Axe + fire", decorated.description());
        assertEquals(1, base.descriptionCalls);
        assertEquals(1, base.damageCalls);
    }

    @Test
    void decorator10_powerDelegatesEachMethodOnceForAnUnknownComponent() {
        CountingWeapon base = new CountingWeapon(13, "Axe");
        WeaponBehavior decorated = new PowerWeapon(base);
        assertEquals(26, decorated.damage());
        assertEquals(1, base.damageCalls);
        assertEquals("Axe x2", decorated.description());
        assertEquals(1, base.descriptionCalls);
        assertEquals(1, base.damageCalls);
    }
}
